      var thr = parseInt(($id("dsh-petfeedhp") || $id("dsh-petfeedhp2")).value, 10) || 25;
      var intv = (parseInt(($id("dsh-petfeedint") || $id("dsh-petfeedint2")).value, 10) || 10) * 1000;
