    zLockCounts = {}; // V1.7.5 重置锁定次数（开/停自动战斗清空）
    dshDiag("zhu-start", { mode: npHuntMode(), panel: (function () { try { return npReadPanelState(); } catch (e) { return null; } })() });
    // 内挂机制寻怪：启动时先校准内挂面板实际开关状态（防用户手动点过内挂开关导致 toggle 不同步），
