      var dd = dirs[zWalkState.dir];
      var tx = px0 + dd[0] * WALK_RANGE;
      var ty = py0 + dd[1] * WALK_RANGE;
      var dDest = mvSnapWalkable(tx, ty);
      var pmm = new (czp("REQUEST_MOVE"))();
