        var pI=arrowSelfPending;
        if(pI&&pI.itid===defIdle){if(now<pI.confirmUntil)return;if(!pI.retryAt){pI.retryAt=now+3000;arrowSelfSay("换回默认箭确认超时，3 秒后重试");return;}if(now<pI.retryAt)return;}
